        then(provider).should().getConnection();
        final LogEvent event = Log4jLogEvent.newBuilder().setLevel(Level.WARN).setLoggerName("com.foo.NoSQLDbTest.testWriteInternal01").setMessage(message).setSource(new StackTraceElement("com.foo.Bar", "testMethod01", "Bar.java", 15)).setThreadId(1L).setThreadName("MyThread-A").setThreadPriority(1).setTimeMillis(1234567890123L).build();
        manager.writeInternal(event, null);
